import json
import collections

# Retrieve parameters directly from the globally injected 'input_data' dictionary
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])
travel_mode = input_data['travel_mode']

def find_path():
    impassable = set()
    water_tiles = set()
    ramps = {(23, 3), (15, 3), (11, 13), (25, 9)}

    # 1F (0_228) map layout database:
    if map_id == "0_228":
        # Let's define water canals (TYPE_4e8c)
        # Western canal: Columns 8, 9, 10, 11
        for y in range(6, 16):
            water_tiles.add((8, y))
            water_tiles.add((9, y))
        for x in [10, 11]:
            water_tiles.add((x, 14))
            water_tiles.add((x, 15))
        # Connection Row 6 and Row 7
        for y in [6, 7]:
            for x in range(10, 14):
                water_tiles.add((x, y))
        # Eastern canal: Columns 14 and 15
        for y in range(4, 13):
            water_tiles.add((14, y))
            water_tiles.add((15, y))

        # Add ramps to water tiles so they are valid targets/starts in surf mode:
        water_tiles.update(ramps)

        # Impassable rock walls on foot (TYPE_2889):
        # Central platform rock blockages:
        impassable.update([
            (17, 13), (14, 14), (13, 13), (13, 14), (15, 15),
            (12, 13), (12, 14), (12, 15), (10, 13), (16, 13),
            (7, 5), (7, 6), (8, 5), (9, 5), (10, 5), (11, 5), (12, 5), (13, 5)
        ])

        # Southern ground barrier at Column 19 Row 15:
        impassable.add((19, 15))

        # Add verified Row 3 and Row 4 rock wall blockages on 1F Northwest (Turn 121415 verification):
        for x in range(3, 13):
            impassable.add((x, 3))
        for x in range(6, 13):
            impassable.add((x, 4))
        for y in range(0, 4):
            impassable.add((4, y))

        # If we are in foot mode, any tile in water_tiles (except ramps) is impassable.
        if travel_mode == "foot":
            impassable.update(water_tiles - ramps)

    # 2F (0_226) map layout database:
    elif map_id == "0_226":
        # Row 16 horizontal rock wall across columns 14 to 20:
        for x in range(14, 21):
            impassable.add((x, 16))
        # Row 9 wall blockages:
        impassable.update([(22, 9), (24, 9)])
        # Row 7 wall blockages:
        impassable.add((17, 7))
        # 2F West Row 8 horizontal rock walls across columns 3 to 12:
        for x in range(3, 13):
            impassable.add((x, 8))
        # Row 10 rock walls across columns 13 to 20:
        for x in range(13, 21):
            impassable.add((x, 10))
        # Northwest isolated walls: (2, 1), (2, 2), (2, 3), (1, 11), (1, 10), (1, 6), (13, 7), (16, 8)
        impassable.update([(2, 1), (2, 2), (2, 3), (1, 11), (1, 10), (1, 6), (13, 7), (16, 8)])

        # Restore critical blockages (Turn 121291 update):
        impassable.update([
            (3, 4), (4, 4), (5, 4), (6, 4), (7, 4), (8, 4), (8, 5),
            (2, 12), (2, 9), (3, 0), (9, 15), (9, 6),
            (13, 11), (13, 16), (16, 13), (9, 2)
        ])

        # Add Row 6 and Row 7 rock blockages (Turn 121306):
        impassable.update([
            (10, 6), (12, 5), (12, 6), (12, 7), (12, 8), (13, 7), (7, 6), (8, 6)
        ])

        # Add newly verified on-foot blockages on the west side to prevent incorrect shortcuts (Turn 121314):
        impassable.update([(2, 4), (1, 4)])

        # Add Row 0 and Row 2 rock walls on 2F West (Turn 121363 verification):
        for x in range(10, 19):
            impassable.add((x, 0))
        for x in range(4, 10):
            impassable.add((x, 2))
        for x in range(0, 7):
            impassable.add((x, 0))

    # Helper function to check if a tile is passable
    def is_passable(x, y):
        if (x, y) in impassable:
            return False
        if travel_mode == "surf":
            # In surf mode, we can only traverse water tiles (which includes ramps)
            return (x, y) in water_tiles
        else:
            # In foot mode, we cannot step onto water tiles (except ramps when dismounting/mounting)
            return (x, y) not in (water_tiles - ramps)

    # To prevent accidental warps, all ladders/stairs/doors (except start/target) are impassable
    warps = {
        "0_228": {(24, 17), (23, 7), (17, 15), (1, 13), (3, 11), (7, 1), (1, 3)},
        "0_226": {(29, 1), (22, 6), (3, 11), (1, 3), (9, 1)}
    }.get(map_id, set())

    # Run BFS
    queue = collections.deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    while queue:
        cx, cy, path = queue.popleft()
        if (cx, cy) == (target_x, target_y):
            return path

        for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy

            # Check map boundaries
            if not (0 <= nx < 30 and 0 <= ny < 30):
                continue
            if (nx, ny) in warps and (nx, ny) != (target_x, target_y):
                continue
            if not is_passable(nx, ny):
                continue

            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, path + [move]))

    return None

path = find_path()
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
